{
  label: "ハッシュが無いか画面を指していなければ構造マップ",
  actual: () => [ScreenChoice.choose(""), ScreenChoice.choose("#"), ScreenChoice.choose("#nope")],
  expected: ["map", "map", "map"],
},

const context = vm.createContext({});
vm.runInContext(script, context);
const core = context.prExplainCore;
if (core === undefined) {
  console.error("document の無い評価で prExplainCore が置かれていない");
  process.exit(2);
}

/** どの画面を開くか。 */
const ScreenChoice = Object.freeze({
  Screens,
  isScreen,
  /**
   * ハッシュが指す画面を選び、指していなければ構造マップを選ぶ。前に開いた画面は見ない。
   *
   * 前に開いた画面を読むと、別の PR の解説も同じ画面で開いてしまうので読まない。
   * PR ごとのキーで覚える形にはしない。同じ PR を開き直したときに構造マップで開かなくなる。
   * @param hash `location.hash`(`#` の有無は問わない)
   * @returns 開く画面
   */
  choose: (hash) => {
    const fromHash = hash.replace(/^#/, "");
    if (isScreen(fromHash)) return fromHash;
    return Screens.Map;
  },
});
